{"path": "bowling.py", "content": "class BowlingGame:
    """Track rolls of a single bowling game and compute its score."""

    FRAMES = 10
    PINS = 10

    def __init__(self):
        self.rolls = []
        self.frame = 1          # current frame number (1-10)
        self.frame_rolls = []   # rolls made in the current frame
        self.finished = False

    def roll(self, pins):
        if self.finished:
            raise IndexError("cannot roll after the game is over")
        if not isinstance(pins, int) or pins < 0:
            raise ValueError("negative roll is invalid")
        if pins > self.PINS:
            raise ValueError("pin count exceeds pins on the lane")

        if self.frame < self.FRAMES:
            self._roll_regular_frame(pins)
        else:
            self._roll_tenth_frame(pins)
        self.rolls.append(pins)

    def _roll_regular_frame(self, pins):
        if self.frame_rolls and self.frame_rolls[0] + pins > self.PINS:
            raise ValueError("pin count exceeds pins on the lane")
        self.frame_rolls.append(pins)
        if pins == self.PINS and len(self.frame_rolls) == 1 or len(self.frame_rolls) == 2:
            self.frame += 1
            self.frame_rolls = []

    def _roll_tenth_frame(self, pins):
        fr = self.frame_rolls
        if len(fr) == 1 and fr[0] < self.PINS and fr[0] + pins > self.PINS:
            raise ValueError("pin count exceeds pins on the lane")
        if len(fr) == 2 and fr[0] == self.PINS and fr[1] < self.PINS \
                and fr[1] + pins > self.PINS:
            raise ValueError("pin count exceeds pins on the lane")
        fr.append(pins)
        if len(fr) == 2 and fr[0] + fr[1] < self.PINS:
            self.finished = True
        elif len(fr) == 3:
            self.finished = True

    def score(self):
        if not self.finished:
            raise IndexError("score cannot be taken until the end of the game")
        total = 0
        i = 0
        rolls = self.rolls
        for _ in range(self.FRAMES):
            if rolls[i] == self.PINS:
                total += self.PINS + rolls[i + 1] + rolls[i + 2]
                i += 1
            elif rolls[i] + rolls[i + 1] == self.PINS:
                total += self.PINS + rolls[i + 2]
                i += 2
            else:
                total += rolls[i] + rolls[i + 1]
                i += 2
        return total
